-- Generated by main 8d8f66a schema 17 setup; no blockers tables.
BEGIN TRANSACTION;
CREATE TABLE agent_routes (
    agent_key  TEXT PRIMARY KEY,
    session_id TEXT,
    state      TEXT NOT NULL CHECK (state IN ('pending', 'unverified', 'final')),
    job        TEXT,
    created_at TEXT NOT NULL
);
CREATE TABLE agents (
    agent_key          TEXT PRIMARY KEY,
    name               TEXT NOT NULL CHECK (length(name) > 0),
    job                TEXT NOT NULL REFERENCES jobs(job) ON DELETE CASCADE,
    role               TEXT,
    host               TEXT,
    joined_at          TEXT NOT NULL,
    last_seen          TEXT NOT NULL,
    last_read_id       INTEGER NOT NULL DEFAULT 0,
    left_at            TEXT,
    state              TEXT NOT NULL DEFAULT 'started'
                       CHECK (state IN ('started', 'running', 'completed', 'left', 'dead')),
    tool_calls         INTEGER NOT NULL DEFAULT 0,
    current_tool       TEXT,
    tool_started_at    TEXT,
    last_post_at       TEXT,
    roster_seen        TEXT,
    roster_synced_at   TEXT,
    memory_recalled_at TEXT,
    memory_seen        TEXT NOT NULL DEFAULT '[]',
    remembered_at      TEXT,
    nudged_at          TEXT,
    reply_reminded_id  INTEGER NOT NULL DEFAULT 0,
    calls_at_post      INTEGER NOT NULL DEFAULT 0,
    silence_nudged_at  TEXT,
    judge              INTEGER NOT NULL DEFAULT 0,
    spawns             INTEGER NOT NULL DEFAULT 0,
    verifier           INTEGER NOT NULL DEFAULT 0
, harness TEXT, model TEXT, turn_ended_at TEXT, os_user TEXT, left_reason TEXT, resume_of TEXT);
CREATE TABLE board_changes (kind TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 0);
INSERT INTO "board_changes" VALUES('messages',1);
INSERT INTO "board_changes" VALUES('state',3);
CREATE TABLE board_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO "board_meta" VALUES('message_max_chars','200');
CREATE TABLE job_pauses (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    job          TEXT NOT NULL,
    paused_at    TEXT NOT NULL,
    paused_by    TEXT,
    reason       TEXT,
    manifest     TEXT NOT NULL,
    resumed_at   TEXT,
    resumed_by   TEXT,
    resumed_host TEXT,
    outcome      TEXT
);
CREATE TABLE jobs (
    job               TEXT PRIMARY KEY,
    description       TEXT,
    created_by        TEXT,
    created_at        TEXT NOT NULL,
    task              TEXT,
    status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active', 'paused', 'completed', 'cancelled', 'failed')),
    outcome           TEXT,
    session_id        TEXT,
    activated_at      TEXT,
    finished_at       TEXT,
    project           TEXT,
    goal              TEXT,
    verdict           TEXT CHECK (verdict IN ('met', 'not_met')),
    verdict_reason    TEXT,
    verdict_next      TEXT,
    verdict_by        TEXT,
    verdict_at        TEXT,
    completion_forced INTEGER NOT NULL DEFAULT 0,
    spawns            INTEGER NOT NULL DEFAULT 0,
    waiting_on        TEXT,
    waiting_since     TEXT,
    waiting_until     TEXT,
    max_hours         REAL,
    plugin_data       TEXT
, closed_by TEXT, supervise INTEGER NOT NULL DEFAULT 1);
