CREATE TABLE restarts (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    job           TEXT NOT NULL,
    agent_key     TEXT NOT NULL,          -- the lineage root: the first agent of the chain
    attempt       INTEGER NOT NULL,
    at            TEXT NOT NULL,
    reason        TEXT NOT NULL,
    old_agent_key TEXT NOT NULL UNIQUE,
    new_agent_key TEXT,
    harness       TEXT NOT NULL,
    host          TEXT NOT NULL,
    os_user       TEXT NOT NULL,
    minutes_cap   REAL NOT NULL,
    ended_at      TEXT,
    outcome       TEXT
);
CREATE TABLE transcript_image_refs (
    job       TEXT NOT NULL,
    agent_key TEXT NOT NULL,
    sha256    TEXT NOT NULL REFERENCES transcript_images (sha256),
    PRIMARY KEY (job, agent_key, sha256)
);
CREATE TABLE transcript_images (
    sha256     TEXT PRIMARY KEY,
    mime       TEXT NOT NULL,
    bytes      INTEGER NOT NULL,
    data       BLOB NOT NULL,
    first_seen TEXT NOT NULL
);
CREATE TABLE transcripts (
    job          TEXT NOT NULL,
    agent_key    TEXT NOT NULL,
    agent_name   TEXT NOT NULL,
    role         TEXT NOT NULL CHECK (role IN ('subagent', 'orchestrator')),
    host         TEXT,
    session_id   TEXT,
    captured_at  TEXT NOT NULL,
    final        INTEGER NOT NULL DEFAULT 0,
    raw_bytes    INTEGER NOT NULL,
    stored_bytes INTEGER NOT NULL,
    redactions   INTEGER NOT NULL DEFAULT 0,
    sha256       TEXT NOT NULL,
    body         BLOB NOT NULL, harness TEXT, capture_failed TEXT,
    PRIMARY KEY (job, agent_key)
);
